"""API request handling and validation."""

from typing import Any


def _validate_request_data(data: object) -> dict[str, Any]:
    """Return *data* after verifying that it is a string-keyed dictionary.

    Request payloads must be dictionaries because downstream processing relies
    on mapping operations. Restricting keys to strings also keeps the payload
    compatible with JSON objects.
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    for key in data:
        if not isinstance(key, str):
            raise TypeError("data keys must be strings")

    return data


def handle_request(data: object):
    """Validate an incoming API request payload before processing it."""
    validated_data = _validate_request_data(data)
    return process(validated_data)

